        { "@type": "Question", "name": "How does a fan certificate work?", "acceptedAnswer": { "@type": "Answer", "text": "When a memorabilia item is authenticated, FanChain issues a non-fungible fan certificate on Polygon. The certificate follows the item on resale, creating a permanent on-chain provenance record for any future buyer." } },
        { "@type": "Question", "name": "Can FanChain help with insurance and valuation?", "acceptedAnswer": { "@type": "Answer", "text": "Yes. FanChain certificates are accepted by leading sports memorabilia insurers and auction houses. Our provenance records simplify the valuation process and can increase realized auction prices." } }
